input.chart:
{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "title": "장기회원 서비스(사단) 연령대별 이벤트 참여율 (2025 vs 2026)",
  "mark": "bar",
  "encoding": {
    "x": {"field": "연령대", "type": "nominal", "title": "연령대", "sort": ["10대 미만","10대","20대","30대","40대","50대","60대","70대","70대 이상","기업","단체","기타"]},
    "y": {"field": "이벤트 참여율(%)", "type": "quantitative", "title": "이벤트 참여율(%)"},
    "xOffset": {"field": "수신연도", "type": "nominal"},
    "color": {"field": "수신연도", "type": "nominal", "title": "수신연도"},
    "tooltip": [
      {"field": "수신연도", "type": "nominal", "title": "수신연도"},
      {"field": "연령대", "type": "nominal", "title": "연령대"},
      {"field": "이벤트 참여율(%)", "type": "quantitative", "title": "이벤트 참여율(%)", "format": ".1f"},
      {"field": "회원수(명)", "type": "quantitative", "title": "회원수(명)"}
    ]
  }
}
